PRAGMA foreign_key_list(productos);

-- Integridad referencial: productos sin categoría válida (debe dar 0)
SELECT COUNT(*) AS huerfanos FROM productos p LEFT JOIN categorias c ON c.id_categoria = p.id_categoria WHERE c.id_categoria IS NULL;

CREATE TABLE socios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nombre TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  edad INTEGER CHECK (edad >= 16),
  alta DATE DEFAULT (date('now'))
);
INSERT INTO socios (nombre, email, edad) VALUES ('Ana', 'ana@ejemplo.es', 20);
SELECT * FROM socios;

CREATE VIEW v_stock_bajo AS
  SELECT p.nombre, c.nombre AS categoria, p.stock FROM productos p JOIN categorias c USING (id_categoria) WHERE p.stock < 10;
SELECT * FROM v_stock_bajo ORDER BY stock;

EXPLAIN QUERY PLAN SELECT * FROM clientes WHERE email = 'ana1@ejemplo.es';
CREATE INDEX idx_clientes_ciudad ON clientes (ciudad);
EXPLAIN QUERY PLAN SELECT * FROM clientes WHERE ciudad = 'Murcia';

SELECT c.nombre AS categoria, COUNT(p.id_producto) AS productos
FROM categorias c LEFT JOIN productos p ON p.id_categoria = c.id_categoria
GROUP BY c.id_categoria ORDER BY productos DESC;

SELECT cl.ciudad, COUNT(DISTINCT p.id_pedido) AS pedidos
FROM pedidos p JOIN clientes cl USING (id_cliente)
GROUP BY cl.ciudad HAVING COUNT(DISTINCT p.id_pedido) >= 3 ORDER BY pedidos DESC;

SELECT p.nombre, p.precio, p.id_categoria FROM productos p
WHERE p.precio > (SELECT AVG(p2.precio) FROM productos p2 WHERE p2.id_categoria = p.id_categoria)
ORDER BY p.id_categoria, p.precio DESC;

WITH ventas AS (
  SELECT p.id_pedido, SUM(l.cantidad * l.precio_unitario) AS importe FROM pedidos p JOIN lineas_pedido l USING (id_pedido) GROUP BY p.id_pedido
)
SELECT id_pedido, ROUND(importe, 2) AS importe, RANK() OVER (ORDER BY importe DESC) AS puesto FROM ventas LIMIT 8;

CREATE TABLE palabras (p TEXT);
INSERT INTO palabras VALUES ('cana'), ('Cana'), ('caña'), ('CAÑA');
SELECT p, p = 'cana' AS exacto, p = 'cana' COLLATE NOCASE AS sin_mayusculas FROM palabras;

-- En MySQL el cotejamiento se elige con COLLATE utf8mb4_0900_ai_ci / _as_cs / es_0900_ai_ci (ver temario UT3)

SELECT COUNT(*) AS igual_null FROM clientes WHERE ciudad = NULL;
SELECT COUNT(*) AS is_null FROM clientes WHERE ciudad IS NULL;
SELECT COUNT(*) AS not_in_mal FROM clientes WHERE id_cliente NOT IN (SELECT id_empleado FROM pedidos);
SELECT COUNT(*) AS not_exists FROM clientes c WHERE NOT EXISTS (SELECT 1 FROM pedidos p WHERE p.id_empleado = c.id_cliente);

SELECT nombre FROM productos WHERE nombre LIKE 'Port%' OR nombre LIKE '%USB%' ORDER BY nombre;
-- GLOB distingue mayúsculas y admite [0-9] (SQLite no trae REGEXP por defecto)
SELECT nombre FROM productos WHERE nombre GLOB '*[0-9][0-9]' ORDER BY nombre;

INSERT INTO categorias (nombre) VALUES ('Gaming');
UPDATE productos SET precio = ROUND(precio * 1.05, 2) WHERE id_categoria = 5;
DELETE FROM categorias WHERE nombre = 'Gaming';
SELECT nombre, precio FROM productos WHERE id_categoria = 5;

BEGIN;
UPDATE productos SET stock = 0;
SELECT SUM(stock) AS stock_total_dentro_de_la_transaccion FROM productos;
ROLLBACK;
SELECT SUM(stock) AS stock_total_tras_rollback FROM productos;

CREATE TABLE resumen (ciudad TEXT PRIMARY KEY, clientes INTEGER);
INSERT INTO resumen SELECT ciudad, COUNT(*) FROM clientes WHERE ciudad IS NOT NULL GROUP BY ciudad;
INSERT INTO resumen VALUES ('Totana', 99) ON CONFLICT(ciudad) DO UPDATE SET clientes = excluded.clientes;
SELECT * FROM resumen ORDER BY clientes DESC;

CREATE TABLE auditoria (id INTEGER PRIMARY KEY AUTOINCREMENT, producto TEXT, antes REAL, despues REAL, cuando TEXT);
CREATE TRIGGER tr_precio AFTER UPDATE OF precio ON productos
BEGIN
  INSERT INTO auditoria (producto, antes, despues, cuando) VALUES (NEW.nombre, OLD.precio, NEW.precio, datetime('now'));
END;
UPDATE productos SET precio = precio + 1 WHERE id_producto IN (1, 2);
SELECT producto, antes, despues FROM auditoria;
